// codebase RAG:  every chunk is currently true
// history RAG:   chunks are true AT A TIME, and supersede each other
//
// Question: "why do we retry payments three times?"
//
//   2023-04  feat: add payment retry (5 attempts)
//   2024-01  fix: reduce retries to 3, gateway rate limits
//   2025-06  chore: make retry count configurable
//
// Cosine will rank these by wording. You need them in ORDER,
// and you need the 2024 one to be the actual answer.

// chunk kinds
{ kind: "message", sha, date, author, text: subject + "\n" + body,
  files: ["src/payment.ts"], issue: 412 }

{ kind: "hunk", sha, date, author, file: "src/payment.ts",
  text: "@@ -18,7 +18,7 @@\n-  retries: 5,\n+  retries: 3,", issue: 412 }

// Retrieve either. Join on sha to present a full answer.

const SEP = "\x1f";       // unit separator, will not appear in messages
const REC = "\x1e";       // record separator

const fmt = ["%H","%at","%an","%ae","%s","%b"].join(SEP) + REC;
const raw = await exec("git log --no-merges --pretty=format:" + fmt);

const commits = raw.split(REC).filter(Boolean).map(r => {
  const [sha, ts, name, email, subject, body] = r.split(SEP);
  return { sha, date: new Date(+ts * 1000), name, email, subject, body };
});

assert(commits.length === Number(await exec("git rev-list --count --no-merges HEAD")));

git log --no-merges --find-renames --numstat --pretty=format:%H
git show --format="" --unified=3 --find-renames <sha> -- <path>

// per file per commit:
{ kind: "hunk", sha, file: "src/payment.ts",
  previousPath: "src/pay.ts",         // if renamed
  added: 4, removed: 4,
  text: "@@ -18,7 +18,7 @@ export function charge(...)\n-  retries: 5,\n+  retries: 3," }

// sanity: total hunks should be roughly 2-4x commit count.
// If it is 50x, a vendored folder or lockfile got in.

const refs = [...text.matchAll(/#(\d+)/g)].map(m => +m[1]);

async function fetchIssue(n: number) {
  if (CACHE[n]) return CACHE[n];
  const r = await gh("/repos/" + REPO + "/issues/" + n);
  CACHE[n] = { title: r.title, body: r.body, url: r.html_url };
  save(CACHE);
  return CACHE[n];
}

// becomes a third chunk kind: { kind: "issue", number, title, body, shas: [...] }

function stale(results, correctSha, outdatedShas) {
  const rc = results.findIndex(r => r.sha === correctSha);
  const ro = results.findIndex(r => outdatedShas.includes(r.sha));
  if (rc === -1) return "missed";
  return (ro !== -1 && ro < rc) ? "stale" : "ok";
}

// baseline expectation on 5 superseded questions:
//   ok 1, stale 3, missed 1
// That is a real problem, clearly stated, with a fix in Phase 4.

by answer source     count   r@5
  commit message        9     0.78
  diff only             4     0.25    <- keyword search will fix
  linked issue         12     0.83
  unanswerable          4      n/a

// Finding for the post: most reasoning is not in the commit at all.
// It is in the PR. Teams that squash without preserving the PR body
// destroy this information permanently.

const lists = [
  vectorSearch(q, messages, 20),
  bm25Search(q, hunks, 20),          // exact tokens, code
  vectorSearch(q, issues, 20)
];
const fused = rrf(lists).slice(0, 10);

// then group by sha so a commit matching on both its message
// and its diff is presented once, with both pieces of evidence.

const byCommit = groupBy(fused, c => c.sha);
const scored = [...byCommit].map(([sha, chunks]) => ({
  sha,
  score: bestRankScore(chunks) * (1 + 0.15 * (distinctKinds(chunks) - 1)),
  evidence: chunks
})).sort((a,b) => b.score - a.score);

// r@5 typically +0.06 from grouping alone, and results become
// much more readable.

const HALF_LIFE_DAYS = 550;
const ageDays = (now - commit.date) / 86400000;
const decay = Math.pow(0.5, ageDays / HALF_LIFE_DAYS);

final = relevance * (0.55 + 0.45 * decay);
// floor of 0.55 so a genuinely old answer can still win
// when nothing recent is relevant

// half-life sweep:
//   200d  staleness 0/5  but r@5 drops to 0.74 (over-corrects)
//   550d  staleness 1/5  r@5 0.84   <- chosen
//  1100d  staleness 2/5  r@5 0.85

// "why does src/payment.ts retry three times"
//   -> path filter: src/payment.ts (+ previousPath src/pay.ts)
//   -> candidate commits: 2,140 -> 38
//
// "why do we retry payments three times"
//   -> no explicit path. Resolve via a first-pass search:
//      top result touches src/payment.ts, so scope to it and re-run.

const scoped = path
  ? chunks.filter(c => c.file === path || c.previousPath === path)
  : chunks;

// overlap index: "src/payment.ts:18-24" -> [a11bc02, a4f21c9, 9f0e3d1]

for (const c of results) {
  const later = overlapping(c).filter(o => o.date > c.date);
  if (later.length) c.supersededBy = later.map(l => l.sha);
}

// presented to the model as an ordered timeline:
//   2023-04  a11bc02  added retry, 5 attempts        [superseded]
//   2024-01  a4f21c9  reduced to 3, gateway limits   [current]
//   2025-06  9f0e3d1  made configurable              [current]

system: You explain why code is the way it is, using commit history.
  - First sentence: the current state and the reason, if recorded.
  - Then the history in order, citing [1] [2].
  - Distinguish what changed (from the diff) from why (from the
    message or issue). Never infer why from a diff alone.
  - If the reason was never written down, say exactly that.

// Good: "Retries are 3 because the gateway rate-limits at 4 rps [2].
//        It was 5 originally [1]."
// Bad:  "Retries were reduced to 3 to improve performance."
//        (nobody wrote that anywhere, the model invented it)

Sources:
